"""Meridian CRM RBAC permission check migration."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *object* and *record*."""
    user_role = user.get("ROLE_ID", "")

    permission = None
    for row in role_rows:
        if (
            row.get("role_id", "") == user_role
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            permission = row
            break

    if permission is None:
        return False

    if action == "DELETE":
        delete_flag = record.get("DEL_FLG", "")
        if delete_flag not in ("", "N"):
            return False

    if user_role == "ADMIN":
        return True

    scope = permission.get("scope", "")
    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
